135→/// Load a single config file and parse it into BivvyConfig.
136→///
137→/// # Errors
138→///
139→/// Returns `ConfigNotFound` if the file doesn't exist.
140→/// Returns `ConfigParseError` if the YAML is invalid.
141→pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
142→    let content = fs::read_to_string(path).map_err(|e| {
143→        if e.kind() == std::io::ErrorKind::NotFound {
144→            BivvyError::ConfigNotFound {
145→                path: path.to_path_buf(),
146→            }
147→        } else {
148→            BivvyError::Io(e)
149→        }
150→    })?;
151→
152→    parse_config(&content, path)
153→}
154→
155→/// Parse YAML content into BivvyConfig.
156→///
157→/// # Arguments
158→///
159→/// * `content` - The YAML content to parse
160→/// * `source_path` - Path for error reporting
161→pub fn parse_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
162→    serde_yaml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
163→        path: source_path.to_path_buf(),
164→        message: e.to_string(),
165→    })
166→}
167→
168→/// Load a config file as raw YAML Value (for merging).
169→///
170→/// Returns the raw serde_yaml::Value without deserializing into
171→/// BivvyConfig, which allows for deep merging before final parsing.
172→pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
173→    let content = fs::read_to_string(path).map_err(|e| {
174→        if e.kind() == std::io::ErrorKind::NotFound {
175→            BivvyError::ConfigNotFound {
176→                path: path.to_path_buf(),
177→            }
178→        } else {
179→            BivvyError::Io(e)
180→        }
181→    })?;
182→
183→    serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
184→        path: path.to_path_buf(),
185→        message: e.to_string(),
186→    })
187→}
188→
189→/// Load and merge all config files for a project.
190→///
191→/// Discovers and merges configs in this order:
192→/// 1. Remote base configs (from `extends:`)
193→/// 2. User global config (`~/.bivvy/config.yml`)
194→/// 3. Project config (`.bivvy/config.yml`)
195→/// 4. Local overrides (`.bivvy/config.local.yml`)
196→///
197→/// # Errors
198→///
199→/// Returns `ConfigNotFound` if no project config exists.
200→/// Returns `ConfigParseError` if any config file is invalid.
201→pub fn load_merged_config(project_root: &Path) -> Result<BivvyConfig> {
202→    load_merged_config_with_resolver(project_root, &ExtendsResolver::default())
203→}
204→
205→/// Load and merge configs with a specific extends resolver.
206→///
207→/// This is the implementation behind `load_merged_config`, exposed
208→/// separately to allow injecting a custom resolver for testing.
209→pub fn load_merged_config_with_resolver(
210→    project_root: &Path,
211→    resolver: &ExtendsResolver,
212→) -> Result<BivvyConfig> {
213→    let paths = ConfigPaths::discover(project_root);
214→
215→    if !paths.has_project_config() {
216→        return Err(BivvyError::ConfigNotFound {
217→            path: project_root.join(".bivvy").join("config.yml"),
218→        });
219→    }
220→
221→    let mut configs = Vec::new();
222→
223→    // Load in merge order
224→    for path in paths.all_existing() {
225→        let value = load_config_value(path)?;
226→        configs.push(value);
227→    }
228→
229→    // Merge all configs
230→    let merged = merge_configs(&configs);
231→
232→    // Parse merged value into typed config
233→    let config: BivvyConfig =
234→        serde_yaml::from_value(merged).map_err(|e| BivvyError::ConfigParseError {
235→            path: project_root.join(".bivvy").join("config.yml"),
236→            message: format!("Failed to parse merged config: {}", e),
237→        })?;
238→
239→    // Resolve extends if present
240→    if config.extends.is_some() {
241→        let resolved = resolver.resolve(&config)?;
242→        Ok(resolved)
243→    } else {
244→        Ok(config)
245→    }
246→}
