 53→    fs::create_dir_all(&bivvy_dir).unwrap();
 54→
 55→    // Base config
 56→    fs::write(
 57→        bivvy_dir.join("config.yml"),
 58→        r#"
 59→app_name: BaseApp
 60→settings:
 61→  default_output: verbose
 62→steps:
 63→  deps:
 64→    command: "yarn install"
 65→"#,
 66→    )
 67→    .unwrap();
 68→
 69→    // Local override
 70→    fs::write(
 71→        bivvy_dir.join("config.local.yml"),
 72→        r#"
 73→settings:
 74→  default_output: quiet
 75→steps:
 76→  deps:
 77→    command: "yarn install --frozen-lockfile"
 78→"#,
 79→    )
 80→    .unwrap();
 81→
 82→    let config = load_merged_config(temp.path()).unwrap();
 83→
 84→    // App name from base
 85→    assert_eq!(config.app_name, Some("BaseApp".to_string()));
 86→
 87→    // Setting overridden by local
 88→    assert_eq!(config.settings.default_output, OutputMode::Quiet);
 89→
 90→    // Step command overridden by local
 91→    assert_eq!(
 92→        config.steps["deps"].command,
 93→        Some("yarn install --frozen-lockfile".to_string())
 94→    );
 95→}
