  1→//! Configuration validation rules.
  2→//!
  3→//! This module validates configuration for correctness:
  4→//! - Steps must have either template or command
  5→//! - depends_on must reference existing steps
  6→//! - Workflows must reference existing steps
  7→//! - No circular dependencies allowed
  8→
  9→use crate::config::schema::BivvyConfig;
 10→use crate::error::{BivvyError, Result};
 11→use std::collections::HashSet;
 12→
 13→/// Validation error with context.
 14→#[derive(Debug, Clone)]
 15→pub struct ValidationError {
 16→    /// Rule identifier
 17→    pub rule: String,
 18→    /// Human-readable error message
 19→    pub message: String,
 20→    /// Step name if error is step-specific
 21→    pub step: Option<String>,
 22→    /// Workflow name if error is workflow-specific
 23→    pub workflow: Option<String>,
 24→}
 25→
 26→/// Validate a configuration and return all errors.
 27→///
 28→/// This function collects all validation errors rather than stopping
 29→/// at the first one, allowing users to fix multiple issues at once.
 30→pub fn validate_config(config: &BivvyConfig) -> Vec<ValidationError> {
 31→    let mut errors = Vec::new();
 32→
 33→    errors.extend(validate_steps(config));
 34→    errors.extend(validate_workflows(config));
 35→    errors.extend(validate_dependencies(config));
 36→
 37→    errors
 38→}
 39→
 40→/// Validate step definitions.
 41→fn validate_steps(config: &BivvyConfig) -> Vec<ValidationError> {
 42→    let mut errors = Vec::new();
 43→
 44→    for (name, step) in &config.steps {
 45→        // Step must have either template or command
 46→        if step.template.is_none() && step.command.is_none() {
 47→            errors.push(ValidationError {
 48→                rule: "missing-command".to_string(),
 49→                message: format!("Step '{}' must have either 'template' or 'command'", name),
 50→                step: Some(name.clone()),
 51→                workflow: None,
 52→            });
 53→        }
 54→
 55→        // Validate depends_on references
 56→        for dep in &step.depends_on {
 57→            if !config.steps.contains_key(dep) {
 58→                errors.push(ValidationError {
 59→                    rule: "unknown-step".to_string(),
 60→                    message: format!("Step '{}' depends on '{}' which does not exist", name, dep),
 61→                    step: Some(name.clone()),
 62→                    workflow: None,
 63→                });
 64→            }
 65→        }
 66→    }
 67→
 68→    errors
 69→}
 70→
 71→/// Validate workflow definitions.
 72→fn validate_workflows(config: &BivvyConfig) -> Vec<ValidationError> {
 73→    let mut errors = Vec::new();
 74→
 75→    for (name, workflow) in &config.workflows {
 76→        // Validate step references
 77→        for step_name in &workflow.steps {
 78→            if !config.steps.contains_key(step_name) {
 79→                errors.push(ValidationError {
 80→                    rule: "unknown-workflow-step".to_string(),
 81→                    message: format!(
 82→                        "Workflow '{}' references step '{}' which does not exist",
 83→                        name, step_name
 84→                    ),
 85→                    step: None,
 86→                    workflow: Some(name.clone()),
 87→                });
 88→            }
 89→        }
 90→
 91→        // Validate override references
 92→        for step_name in workflow.overrides.keys() {
 93→            if !workflow.steps.contains(step_name) {
 94→                errors.push(ValidationError {
 95→                    rule: "unknown-override-step".to_string(),
 96→                    message: format!(
 97→                        "Workflow '{}' has override for '{}' which is not in the workflow",
 98→                        name, step_name
 99→                    ),
100→                    step: None,

  1→//! Remote configuration fetching.
  2→//!
  3→//! This module provides functionality for fetching configuration files
  4→//! from remote URLs.
  5→
  6→use anyhow::{anyhow, Context, Result};
  7→use std::collections::HashMap;
  8→use std::path::PathBuf;
  9→use std::time::Duration;
 10→
 11→/// Fetches remote configuration files with caching.
 12→///
 13→/// # Example
 14→///
 15→/// ```no_run
 16→/// use bivvy::config::RemoteFetcher;
 17→/// use std::time::Duration;
 18→///
 19→/// let fetcher = RemoteFetcher::new(Duration::from_secs(30));
 20→///
 21→/// // Fetch a remote config file
 22→/// let content = fetcher.fetch("https://example.com/config.yml").unwrap();
 23→/// ```
 24→pub struct RemoteFetcher {
 25→    /// Request timeout.
 26→    timeout: Duration,
 27→    /// Cache directory for downloaded configs.
 28→    cache_dir: PathBuf,
 29→    /// HTTP client.
 30→    client: reqwest::blocking::Client,
 31→}
 32→
 33→impl RemoteFetcher {
 34→    /// Create a fetcher with the specified timeout.
 35→    pub fn new(timeout: Duration) -> Self {
 36→        let cache_dir = dirs::cache_dir()
 37→            .unwrap_or_else(|| PathBuf::from("~/.cache"))
 38→            .join("bivvy")
 39→            .join("remote-configs");
 40→
 41→        Self {
 42→            timeout,
 43→            cache_dir,
 44→            client: reqwest::blocking::Client::builder()
 45→                .timeout(timeout)
 46→                .build()
 47→                .expect("Failed to create HTTP client"),
 48→        }
 49→    }
 50→
 51→    /// Create a fetcher with a custom cache directory.
 52→    pub fn with_cache_dir(timeout: Duration, cache_dir: PathBuf) -> Self {
 53→        Self {
 54→            timeout,
 55→            cache_dir,
 56→            client: reqwest::blocking::Client::builder()
 57→                .timeout(timeout)
 58→                .build()
 59→                .expect("Failed to create HTTP client"),
 60→        }
 61→    }
 62→
 63→    /// Fetch a configuration file from a URL.
 64→    pub fn fetch(&self, url: &str) -> Result<String> {
 65→        // Check cache first
 66→        if let Some(cached) = self.check_cache(url)? {
 67→            return Ok(cached);
 68→        }
 69→
 70→        // Fetch from remote
 71→        let content = self.fetch_remote(url)?;
 72→
 73→        // Cache the result
 74→        self.save_cache(url, &content)?;
 75→
 76→        Ok(content)
 77→    }
 78→
 79→    /// Fetch a configuration file, bypassing cache.
 80→    pub fn fetch_fresh(&self, url: &str) -> Result<String> {
 81→        self.fetch_remote(url)
 82→    }
 83→
 84→    /// Fetch with authentication header.
 85→    pub fn fetch_with_auth(&self, url: &str, auth: &AuthHeader) -> Result<String> {
 86→        let response = self
 87→            .client
 88→            .get(url)
 89→            .header(&auth.header_name, &auth.header_value)
 90→            .send()
 91→            .with_context(|| format!("Failed to fetch {}", url))?;
 92→
 93→        if !response.status().is_success() {
 94→            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
 95→        }
 96→
 97→        response
 98→            .text()
 99→            .with_context(|| format!("Failed to read response from {}", url))
100→    }

