  2→//!
  3→//! The `bivvy config` command shows resolved configuration.
  4→
  5→use std::path::{Path, PathBuf};
  6→
  7→use crate::cli::args::ConfigArgs;
  8→use crate::config::{load_merged_config, ConfigPaths};
  9→use crate::error::{BivvyError, Result};
 10→use crate::ui::{OutputMode, UserInterface};
 11→
 12→use super::dispatcher::{Command, CommandResult};
 13→
 14→/// The config command implementation.
 15→pub struct ConfigCommand {
 16→    project_root: PathBuf,
 17→    args: ConfigArgs,
 18→}
 19→
 20→impl ConfigCommand {
 21→    /// Create a new config command.
 22→    pub fn new(project_root: &Path, args: ConfigArgs) -> Self {
 23→        Self {
 24→            project_root: project_root.to_path_buf(),
 25→            args,
 26→        }
 27→    }
 28→
 29→    /// Get the project root path.
 30→    pub fn project_root(&self) -> &Path {
 31→        &self.project_root
 32→    }
 33→
 34→    /// Get the command arguments.
 35→    pub fn args(&self) -> &ConfigArgs {
 36→        &self.args
 37→    }
 38→}
 39→
 40→impl Command for ConfigCommand {
 41→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
 42→        // Load configuration
 43→        let config = match load_merged_config(&self.project_root) {
 44→            Ok(c) => c,
 45→            Err(BivvyError::ConfigNotFound { .. }) => {
 46→                ui.error("No configuration found. Run 'bivvy init' first.");
 47→                return Ok(CommandResult::failure(2));
 48→            }
 49→            Err(e) => return Err(e),
 50→        };
 51→
 52→        // Apply config default_output when no CLI flag was explicitly set
 53→        if ui.output_mode() == OutputMode::Normal {
 54→            ui.set_output_mode(config.settings.default_output.into());
 55→        }
 56→
 57→        // Show config file path(s)
 58→        let paths = ConfigPaths::discover(&self.project_root);
 59→        let existing: Vec<_> = paths.all_existing();
 60→        if !existing.is_empty() {
 61→            for path in &existing {
 62→                ui.message(&format!("# {}", path.display()));
 63→            }
 64→            ui.message("");
 65→        }
 66→
 67→        // Output format
 68→        if self.args.json {
 69→            let json =
 70→                serde_json::to_string_pretty(&config).map_err(|e| BivvyError::Other(e.into()))?;
 71→            ui.message(&json);
 72→        } else {
 73→            let yaml = serde_yaml::to_string(&config).map_err(|e| BivvyError::Other(e.into()))?;
 74→            ui.message(&yaml);
 75→        }
 76→
 77→        Ok(CommandResult::success())
 78→    }
 79→}
