 80→            continue;
 81→        }
 82→
 83→        // Parse KEY=value
 84→        if let Some(eq_pos) = line.find('=') {
 85→            let key = line[..eq_pos].trim().to_string();
 86→            let mut value = line[eq_pos + 1..].trim().to_string();
 87→
 88→            // Remove surrounding quotes if present
 89→            if ((value.starts_with('"') && value.ends_with('"'))
 90→                || (value.starts_with('\'') && value.ends_with('\'')))
 91→                && value.len() >= 2
 92→            {
 93→                value = value[1..value.len() - 1].to_string();
 94→            }
 95→
 96→            env.insert(key, value);
 97→        } else {
 98→            return Err(BivvyError::ConfigParseError {
 99→                path: source_path.to_path_buf(),
100→                message: format!("Invalid line {}: {}", line_num + 1, line),

